INSERT INTO hotel (Hotel_id,Hotel_name,Hotel_city,Hotel_description,Hotel_address,Hotel_phone_no,Hotel_email,Hotel_rating,Hotel_amenities,Hotel_image) VALUES
(1,'Azure Sands Beach Resort','Goa','A beachfront resort on Candolim beach with palm-lined pools, a sunset bar and a full-service spa. Wake up to the sound of waves.','Candolim Beach Road, Candolim, Goa 403515','+91 832 555 0101','stay@azuresands.example',5,'Wi-Fi,Swimming Pool,Spa,Beach Access,Restaurant,Bar,Airport Shuttle,Gym','demo_goa.jpg'),
(2,'Rajmahal Heritage Palace','Jaipur','A restored 19th century palace in the Pink City, with courtyards, folk music evenings and Rajasthani royal cuisine.','Amer Road, Jaipur, Rajasthan 302002','+91 141 555 0102','book@rajmahal.example',5,'Wi-Fi,Swimming Pool,Spa,Restaurant,Heritage Walks,Airport Shuttle,Gym,Bar','demo_jaipur.jpg'),
(3,'Harbor Lights Grand','Mumbai','A luxury high-rise at the Mumbai waterfront with skyline views, a rooftop infinity pool and five dining venues.','Marine Drive, Mumbai, Maharashtra 400020','+91 22 5550 0103','hello@harborlights.example',5,'Wi-Fi,Rooftop Pool,Spa,Restaurant,Bar,Business Center,Gym,Valet Parking','demo_mumbai.jpg'),
(4,'Lake Pichola Haveli','Udaipur','A heritage haveli on the banks of Lake Pichola. Dine on the rooftop with the City Palace glowing across the water.','Gangaur Ghat Marg, Udaipur, Rajasthan 313001','+91 294 555 0104','stay@picholahaveli.example',4,'Wi-Fi,Lake View,Restaurant,Rooftop Dining,Spa,Heritage Walks,Airport Shuttle','demo_udaipur.jpg'),
(5,'Snowpeak Retreat','Manali','Cosy wooden cottages surrounded by deodar forest with views of the snow-capped Pir Panjal range.','Old Manali Road, Manali, Himachal Pradesh 175131','+91 190 255 0105','info@snowpeak.example',4,'Wi-Fi,Room Heater,Bonfire,Restaurant,Mountain View,Trekking Desk,Parking','demo_manali.jpg'),
(6,'Backwater Bliss Resort','Kochi','A tranquil resort on the Kochi backwaters. Take a sunset houseboat cruise and taste fresh Kerala seafood.','Willingdon Island, Kochi, Kerala 682003','+91 484 555 0106','stay@backwaterbliss.example',4,'Wi-Fi,Swimming Pool,Ayurveda Spa,Houseboat Cruise,Restaurant,Kayaking,Parking','demo_kochi.jpg'),
(7,'Silicon Stay Suites','Bengaluru','Smart business hotel near the tech parks with fast fibre Wi-Fi, a co-working lounge and early breakfast.','Outer Ring Road, Marathahalli, Bengaluru 560037','+91 80 5550 0107','desk@siliconstay.example',3,'Wi-Fi,Business Center,Restaurant,Gym,Airport Shuttle,Parking,Co-working Lounge','demo_bengaluru.jpg'),
(8,'Ganga Valley Yoga Retreat','Rishikesh','A peaceful riverside retreat with daily yoga, guided meditation and a wholesome vegetarian kitchen.','Laxman Jhula Road, Rishikesh, Uttarakhand 249302','+91 135 555 0108','namaste@gangavalley.example',3,'Wi-Fi,Yoga Studio,Meditation Hall,Vegetarian Restaurant,River View,Rafting Desk,Parking','demo_rishikesh.jpg');
INSERT INTO room_type (Room_type_id,Room_type_name,Room_type_description,Room_type_capacity,Room_type_price_per_night) VALUES
(1,'Standard Room','Comfortable room with a queen bed, work desk, air-conditioning, free Wi-Fi and a private bathroom.',2,2200.00),
(2,'Deluxe Room','Spacious room with a king bed, sitting area, minibar and a city or garden view.',3,3800.00),
(3,'Family Room','Two double beds and extra space for four guests, with a kids'' corner and a large wardrobe.',4,5200.00),
(4,'Executive Suite','Separate lounge and bedroom, executive lounge access, complimentary breakfast and evening snacks.',3,7200.00),
(5,'Presidential Suite','Our finest suite: panoramic views, private dining, butler service and a jacuzzi bath.',4,14500.00),
(6,'Budget Single','Compact, clean single room with Wi-Fi, a hot shower and 24x7 reception - ideal for solo travellers.',1,900.00),
(7,'Sea View Deluxe','Deluxe room with a private balcony facing the sea, rain shower and breakfast included.',3,6400.00),
(8,'Heritage Suite','Hand-painted interiors, antique furniture and a jharokha window - a royal stay.',3,9800.00),
(9,'Mountain Cottage','Wooden cottage with a fireplace, private deck and valley views. Room heater included.',4,4600.00);
